  // Validate promo/discount code and return discount percentage
  app.post("/api/partner/validate-promo", isAuthenticated, async (req: any, res) => {
    try {
      const { promoCode } = req.body;
      if (!promoCode || typeof promoCode !== 'string') {
        return res.status(400).json({ valid: false, message: "Promo code is required" });
      }

      const normalized = promoCode.trim().toUpperCase();

      const knownCodes: Record<string, { percentOff: number; name: string }> = {
        'FREE': { percentOff: 100, name: 'Free Access (100% off)' },
        '20OFFPRICE': { percentOff: 20, name: '20% Discount' },
        'DISCOUNT': { percentOff: 99, name: 'Partner Discount (99% off)' },
      };

      const match = knownCodes[normalized];
      if (match) {
        return res.json({ valid: true, percentOff: match.percentOff, name: match.name, code: normalized });
      }

      return res.json({ valid: false, message: "Invalid promo code" });
    } catch (error: any) {
      console.error("Error validating promo code:", error);
      res.status(500).json({ valid: false, message: "Failed to validate promo code" });
    }
  });

    // Partner self-service: Create checkout session for test package purchase
  app.post("/api/partner/purchase/checkout", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      const hasPartnerAccess = user?.role === 'super_admin' || user?.role === 'organization_admin' || user?.role === 'partner_admin';
      if (!hasPartnerAccess) {
        return res.status(403).json({ message: "Forbidden: Partner access required" });
      }
      
      // Find partner account associated with this user's organisation
      let matchingPartner = null;
      
      if (user?.organizationId) {
        matchingPartner = await storage.getPartnerAccountByOrganizationId(user.organizationId);
      }
      
      if (!matchingPartner && user?.email) {
        matchingPartner = await storage.getPartnerAccountByEmail(user.email);
      }
      
      if (!matchingPartner && user?.organizationId) {
        const org = await storage.getOrganization(user.organizationId);
        if (org) {
          const partners = await storage.getAllPartnerAccounts();
          matchingPartner = partners.find(p => 
            p.companyName?.toLowerCase() === org.name.toLowerCase()
          ) || null;
        }
      }
      
      if (!matchingPartner) {
        return res.status(404).json({ message: "No partner account found for your organisation" });
      }
      
      // Only PAYG and Subscription billing type partners can self-purchase
      if (matchingPartner.billingType !== 'payg' && matchingPartner.billingType !== 'subscription') {
        return res.status(400).json({ 
          message: "Self-service purchasing is only available for Pay As You Go and Subscription billing accounts. Enterprise clients should contact their account manager." 
        });
      }
      
      const { packageSize, promoCode } = req.body;
      if (!packageSize || typeof packageSize !== 'number' || packageSize < 10) {
        return res.status(400).json({ message: "Package size must be at least 10 tests" });
      }
      
      // Use partner's assigned currency and pricing (no PPP adjustment for B2B partners)
      // Partners have negotiated pricing that should not change based on their location
      const partnerCurrency = (matchingPartner.currency || 'GBP').toLowerCase();
      const displayCurrency = partnerCurrency;
      const basePricePerTest = matchingPartner.pricePerAssessment || 500;
      
      // No PPP adjustment for B2B partners - they pay their assigned rate
      const pppAdjustedPricePerTest = basePricePerTest;
      
      // Subscription discount tiers - only subscription users get discounts
      const billingType = matchingPartner.billingType || 'payg';
      const subscriptionDiscounts = [2, 4, 6, 8, 10, 15]; // For tiers: 10, 25, 50, 100, 250, 500
      
      // Volume discount tiers - must match the pricing API
      const packageTiers = [
        { size: 10, name: 'Starter' },
        { size: 25, name: 'Growth' },
        { size: 50, name: 'Professional' },
        { size: 100, name: 'Business' },
        { size: 250, name: 'Enterprise' },
        { size: 500, name: 'Enterprise+' },
      ].map((tier, index) => ({
        ...tier,
        // Only subscription users get discounts
        discountPercent: billingType === 'subscription' ? subscriptionDiscounts[index] : 0,
      }));
      
      // Find matching tier or use no discount for custom sizes
      const tier = packageTiers.find(t => t.size === packageSize);
      const discountPercent = tier?.discountPercent || 0;
      const discountMultiplier = 1 - (discountPercent / 100);
      const pricePerTest = Math.round(pppAdjustedPricePerTest * discountMultiplier);
      const totalPrice = pricePerTest * packageSize;
      
      // Create package record (pending)
      const pkg = await storage.createPartnerTestPackage({
        partnerId: matchingPartner.id,
        packageSize,
        pricePerTest,
        totalPrice,
        currency: displayCurrency,
        status: 'pending',
      });
      
      console.log(`[Partner Purchase] Partner: ${matchingPartner.id}, Partner Currency: ${displayCurrency}, PPP: 1 (no adjustment), Price: ${totalPrice}, Promo: ${promoCode || 'none'}`);
      
      // Route through payment provider system
      console.log(`[Partner Purchase] Partner paymentProvider field: '${matchingPartner.paymentProvider}', type: ${typeof matchingPartner.paymentProvider}`);
      const { primary, fallback } = getPaymentProviders(matchingPartner.paymentProvider);
      console.log(`[Partner Purchase] Routing decision: primary=${primary}, fallback=${fallback}`);
      
      // Get currency symbol for description
      const currencySymbols: Record<string, string> = {
        gbp: '\u00a3', usd: '\u0024', eur: '\u20ac', aud: 'A\u0024', cad: 'C\u0024', sgd: 'S\u0024', hkd: 'HK\u0024',
        inr: '\u20b9', myr: 'RM', thb: '\u0e3f', php: '\u20b1', jpy: '\u00a5',
      };
      const currSymbol = currencySymbols[displayCurrency] || displayCurrency.toUpperCase() + ' ';
      const isZeroDecimal = ['jpy', 'krw', 'vnd', 'idr', 'clp', 'pyg', 'ugx', 'gnf', 'kmf', 'rwf', 'xof', 'xaf', 'xpf', 'djf', 'bif', 'mga', 'vuv'].includes(displayCurrency);
      const displayPriceAmount = isZeroDecimal ? pricePerTest : (pricePerTest / 100);
      
      // Check promo code (used for Stripe checkout)
      let promoCodeId: string | undefined;
      if (promoCode && promoCode.trim()) {
        try {
          const stripeClient = new (await import("stripe")).default(process.env.STRIPE_SECRET_KEY!);
          const promoCodes = await stripeClient.promotionCodes.list({
            code: promoCode.trim().toUpperCase(),
            active: true,
            limit: 1,
          });
          if (promoCodes.data.length > 0) {
            promoCodeId = promoCodes.data[0].id;
            console.log(`[Partner Purchase] Found valid promo code: ${promoCode} -> ${promoCodeId}`);
          } else {
            console.log(`[Partner Purchase] Promo code not found: ${promoCode}`);
          }
        } catch (err) {
          console.log(`[Partner Purchase] Error checking promo code: ${err}`);
        }
      }
      
      const baseUrl = getRoutesBaseUrl(req);

      // Handle promo codes for Airwallex partners - apply discount at app level
      let adjustedTotalPrice = totalPrice;
      const normalizedPromo = promoCode ? promoCode.trim().toUpperCase() : '';
      const appLevelPromoCodes: Record<string, number> = {
        'FREE': 100,
        '20OFFPRICE': 20,
        'DISCOUNT': 99,
      };
      const promoDiscountPercent = appLevelPromoCodes[normalizedPromo] || 0;
      if (promoDiscountPercent > 0) {
        adjustedTotalPrice = Math.round(totalPrice * (1 - promoDiscountPercent / 100));
      }
      if (adjustedTotalPrice === 0 && promoDiscountPercent > 0) {
        // For zero-amount, grant access immediately
        await storage.updatePartnerTestPackage(pkg.id, {
          status: 'completed',
          totalPrice: 0,
          paymentProvider: matchingPartner.paymentProvider || 'airwallex',
        });
        await storage.creditPartnerTests(
          matchingPartner.id,
          pkg.id,
          packageSize,
          `Package purchase: ${packageSize} tests (FREE promo code)`
        );
        console.log(`[Partner Purchase] FREE promo applied - credited ${packageSize} tests to partner ${matchingPartner.id}`);
        const freeSuccessUrl = `${baseUrl}/partner-package-success?provider=airwallex&packageId=${pkg.id}&promo=free`;
        return res.json({
          success: true,
          free: true,
          sessionUrl: freeSuccessUrl,
          message: `${packageSize} tests credited successfully with FREE promo code`,
          packageId: pkg.id,
        });
      }
      
      const airwallexPurchaseFn = async (): Promise<PaymentCheckoutResult> => {
        const airwallexAmount = formatAmountForAirwallex(adjustedTotalPrice, displayCurrency.toUpperCase());
        const merchantOrderId = `partner_pkg_${pkg.id}_${Date.now()}`;
        
        const intent = await createPaymentIntent({
          amount: airwallexAmount,
          currency: displayCurrency.toUpperCase(),
          merchantOrderId,
          returnUrl: `${baseUrl}/partner-package-success?provider=airwallex&packageId=${pkg.id}`,
          customerEmail: matchingPartner.billingEmail || matchingPartner.email,
          description: `HumanMetrix Test Package - ${packageSize} Tests`,
          metadata: {
            type: 'partner_package',
            partnerId: matchingPartner.id,
            packageId: pkg.id,
            packageSize: packageSize.toString(),
            selfService: 'true',
          },
        });
        
        await storage.updatePartnerTestPackage(pkg.id, {
          airwallexPaymentIntentId: intent.id,
          paymentProvider: 'airwallex',
        });
        
        return {
          provider: 'airwallex',
          intentId: intent.id,
          clientSecret: intent.clientSecret,
          amount: airwallexAmount,
          currency: displayCurrency.toUpperCase(),
          returnUrl: `${baseUrl}/partner-package-success?provider=airwallex&packageId=${pkg.id}`,
          packageId: pkg.id,
        };
      };
      
      const stripePurchaseFn = async (): Promise<PaymentCheckoutResult> => {
        const stripeClient = new (await import("stripe")).default(process.env.STRIPE_SECRET_KEY!);
        
        let customerId = matchingPartner.stripeCustomerId;
        if (!customerId) {
          const customer = await stripeClient.customers.create({
            email: matchingPartner.billingEmail || matchingPartner.email,
            name: matchingPartner.companyName || matchingPartner.name,
            metadata: {
              partnerId: matchingPartner.id,
              partnerName: matchingPartner.name,
            },
          });
          customerId = customer.id;
          await storage.updatePartnerAccount(matchingPartner.id, {
            stripeCustomerId: customerId,
          });
        }
        
        const session = await stripeClient.checkout.sessions.create({
          payment_method_types: ['card'],
          mode: 'payment',
          adaptive_pricing: { enabled: false },
          customer: customerId,
          allow_promotion_codes: !promoCodeId,
          ...(promoCodeId ? { discounts: [{ promotion_code: promoCodeId }] } : {}),
          line_items: [{
            price_data: {
              currency: displayCurrency,
              product_data: {
                name: `HumanMetrix Test Package - ${packageSize} Tests`,
                description: `${tier?.name || 'Custom'} package: ${packageSize} assessment credits at ${currSymbol}${displayPriceAmount.toFixed(isZeroDecimal ? 0 : 2)} per test${discountPercent > 0 ? ` (${discountPercent}% volume discount)` : ''}`,
              },
              unit_amount: totalPrice,
            },
            quantity: 1,
          }],
          metadata: {
            type: 'partner_package',
            partnerId: matchingPartner.id,
            packageId: pkg.id,
            packageSize: packageSize.toString(),
            selfService: 'true',
            discountPercent: discountPercent.toString(),
          },
          success_url: `${baseUrl}/partner-package-success?session_id={CHECKOUT_SESSION_ID}`,
          cancel_url: `${baseUrl}/partner?tab=billing&purchase_cancelled=true`,
        });
        
        await storage.updatePartnerTestPackage(pkg.id, {
          stripeCheckoutSessionId: session.id,
          paymentProvider: 'stripe',
        });
        
        return { provider: 'stripe', url: session.url, packageId: pkg.id };
      };
      
      const purchaseResult = await createCheckoutWithFallback(primary, fallback, airwallexPurchaseFn, stripePurchaseFn);
      
      if (purchaseResult.provider === 'airwallex') {
        res.json({
          success: true,
          paymentProvider: 'airwallex',
          airwallexEnv,
          intentId: purchaseResult.intentId,
          clientSecret: purchaseResult.clientSecret,
          amount: purchaseResult.amount,
          currency: purchaseResult.currency,
          returnUrl: purchaseResult.returnUrl,
          packageId: purchaseResult.packageId,
        });
      } else {
        res.json({
          success: true,
          paymentProvider: 'stripe',
          sessionUrl: purchaseResult.url,
          packageId: purchaseResult.packageId,
        });
      }
    } catch (error) {
      console.error("Error creating partner self-service checkout:", error);
      res.status(500).json({ message: "Failed to create checkout session" });
    }
  });


  // ==================== PARTNER INTEGRATION MANAGEMENT ====================
  
  // Helper function to get partner for authenticated user (including team members)
  async function getPartnerForUser(userId: string): Promise<{ partner: any; teamMemberRole?: string; isTeamMember?: boolean; isAdmin?: boolean } | null> {
    const user = await storage.getUser(userId);
    if (!user) return null;
    
    // Partner admins, org admins, and super admins can access partner features directly
    const hasPartnerAccess = user.role === 'super_admin' || user.role === 'organization_admin' || user.role === 'partner_admin';
    
    let partner = null;
    
    if (hasPartnerAccess) {
      if (user.organizationId) {
        partner = await storage.getPartnerAccountByOrganizationId(user.organizationId);
      }
      if (!partner && user.email) {
        partner = await storage.getPartnerAccountByEmail(user.email);
      }
      if (partner) {
        return { partner, isTeamMember: false, isAdmin: true };
      }
    }
    
    // Check if user is a team member of a partner
    const teamMembership = await storage.getPartnerTeamMemberByUserId(userId);
    if (teamMembership) {
      partner = await storage.getPartnerAccount(teamMembership.partnerId);
      if (partner) {
        // Team members with 'admin' or 'owner' role have admin access
        const isAdmin = teamMembership.role === 'admin' || teamMembership.role === 'owner';
        return { partner, teamMemberRole: teamMembership.role, isTeamMember: true, isAdmin };
      }
    }
    
    return null;
  }
  
  // Helper to require admin access for sensitive partner endpoints
  function requirePartnerAdmin(partnerData: { isAdmin?: boolean } | null): boolean {
    return partnerData?.isAdmin === true;
  }
  
  // Role hierarchy for partner team members
  // viewer < member < admin < owner
  const ROLE_HIERARCHY: Record<string, number> = {
    'viewer': 1,
    'member': 2,
    'admin': 3,
    'owner': 4,
  };
  
  // Helper to check if user has at least the required role level
  // Direct partner admins (isAdmin=true, isTeamMember=false) have full access
  function requirePartnerRole(
    partnerData: { isAdmin?: boolean; isTeamMember?: boolean; teamMemberRole?: string } | null,
    minRole: 'viewer' | 'member' | 'admin' | 'owner'
  ): boolean {
    if (!partnerData) return false;
    
    // Direct partner admins (not team members) have full access
    if (partnerData.isAdmin && !partnerData.isTeamMember) {
      return true;
    }
    
    // For team members, check role hierarchy
    const userRole = partnerData.teamMemberRole;
    if (!userRole) return false;
    
    const userLevel = ROLE_HIERARCHY[userRole] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[minRole] ?? 0;
    
    return userLevel >= requiredLevel;
  }

