  app.get("/api/partner/me/compare", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      // Support both candidateIds and userIds parameter names for compatibility with shared components
      const rawCandidateIds = req.query.candidateIds || req.query.userIds;
      const forceRefresh = req.query.forceRefresh === 'true';
      const candidateIds = Array.isArray(rawCandidateIds)
        ? rawCandidateIds as string[]
        : [rawCandidateIds as string].filter(Boolean);

      if (!candidateIds || candidateIds.length < 1) {
        return res.status(400).json({ message: "At least 1 candidate ID required" });
      }

      // Normalize assessment type for comparison
      const normalizeAssessmentType = (type: string) => 
        type.toLowerCase().replace(/[\s-]+/g, '_');
      
      // Skill name normalization map
      const normalizeSkillName = (skill: string): string => {
        const skillMap: Record<string, string> = {
          'AI Literacy': 'AI Literacy & Prompt Engineering',
          'AI Literacy/Prompting': 'AI Literacy & Prompt Engineering',
          'Technical Fluency': 'Technical Fundamentals',
          'Domain Fluency': 'Data Fluency',
          'Critical Thinking': 'Critical Thinking & Problem-Solving',
          'Adaptive Learning': 'Adaptability & Continuous Learning',
          'Collaboration': 'Collaboration & Communication',
          'Cross-functional Collaboration': 'Collaboration & Communication',
          'Responsible AI': 'Responsible AI & Ethical Awareness',
          'Creative Innovation': 'Creativity & Innovation',
        };
        return skillMap[skill] || skill;
      };

      // Build candidate results from B2B sessions only
      // This mirrors the logic in /api/partner/me/candidates endpoint
      
      // SOURCE 1: B2B Widget/API sessions
      const allSessions = await storage.getSessionsByPartner(partner.id, 10000);
      const completedSessions = allSessions.filter(s => s.status === 'completed' && !s.isTestSession);
      
      // Build a map of candidate results with result IDs for evaluation fetching
      type ResultWithId = {
        id: string;
        assessmentType: string;
        scores: any;
        totalScore: number;
        completedAt: Date | null;
        status: string;
        percentile?: number;
        isFromAssessmentResults: boolean;
        evaluations?: any;
      };
      
      const candidateResultsMap = new Map<string, ResultWithId[]>();
      
      // Initialize map for all requested candidates
      for (const candidateId of candidateIds) {
        candidateResultsMap.set(candidateId, []);
      }
      
      // Add session-based results
      for (const session of completedSessions) {
        const email = session.externalEmail || session.externalUserId || session.id;
        
        if (candidateIds.includes(email)) {
          const results = candidateResultsMap.get(email) || [];
          results.push({
            id: session.id,
            assessmentType: session.assessmentType,
            scores: session.scores || {},
            totalScore: session.totalScore || 0,
            completedAt: session.completedAt,
            status: session.status,
            percentile: 0, // Sessions don't have percentile
            isFromAssessmentResults: false,
            evaluations: session.evaluations || null,
          });
          candidateResultsMap.set(email, results);
        }
      }
      
      // Convert map to array in candidateIds order
      const candidatesResults = candidateIds.map(id => {
        const results = candidateResultsMap.get(id) || [];
        return results.sort((a, b) => {
          const dateA = a.completedAt ? new Date(a.completedAt).getTime() : 0;
          const dateB = b.completedAt ? new Date(b.completedAt).getTime() : 0;
          return dateB - dateA; // Most recent first
        });
      });

      // Validate all candidates belong to this partner - check if they have any data
      // Get the full set of valid partner candidate IDs
      const validPartnerCandidateIds = new Set<string>();
      completedSessions.forEach(s => {
        if (s.externalEmail) validPartnerCandidateIds.add(s.externalEmail);
        if (s.externalUserId) validPartnerCandidateIds.add(s.externalUserId);
        if (s.id) validPartnerCandidateIds.add(s.id);
      });
      
      const unauthorizedCandidates = candidateIds.filter(id => !validPartnerCandidateIds.has(id));
      if (unauthorizedCandidates.length > 0) {
        return res.status(403).json({ 
          message: "Some candidates do not belong to your organization",
          unauthorizedCandidates 
        });
      }

      // Check for existing cached report (unless forceRefresh is requested)
      // Use correct report type based on candidate count
      const cachedReportType = candidateIds.length === 1 ? 'individual' : 'comparison';
      let hasIncompleteCachedReport = false;
      
      if (!forceRefresh) {
        const existingReport = await storage.findExistingPartnerReport(
          partner.id,
          cachedReportType,
          candidateIds
        );
        if (existingReport) {
          const resultData = existingReport.resultData as any;
          if (resultData && resultData.aiInsights && resultData.scoringVersion >= 2) {
            return res.json({
              ...resultData,
              cached: true,
              cachedAt: existingReport.createdAt,
              generatedAt: existingReport.createdAt,
              reportId: existingReport.id,
            });
          }
          hasIncompleteCachedReport = false;
        }
      }

      const skillBasedAssessmentTypes = ['fit', 'ai_readiness', 'ai-readiness'];
      
      // Build skills map for radar chart
      const skillsMap = new Map<string, (number | null)[]>();
      
      candidatesResults.forEach((results, candidateIndex) => {
        const skillBasedResults = results.filter((r) => {
          const normalized = normalizeAssessmentType(r.assessmentType);
          return skillBasedAssessmentTypes.some(type => normalizeAssessmentType(type) === normalized);
        });
        
        skillBasedResults.forEach((result) => {
          if (result.scores && typeof result.scores === 'object') {
            Object.entries(result.scores).forEach(([skill, score]) => {
              const canonicalSkill = normalizeSkillName(skill);
              if (!skillsMap.has(canonicalSkill)) {
                skillsMap.set(canonicalSkill, new Array(candidateIds.length).fill(null));
              }
              const scores = skillsMap.get(canonicalSkill)!;
              scores[candidateIndex] = score as number;
            });
          }
        });
      });

      // Build radar data
      const radarData: any[] = [];
      skillsMap.forEach((scores, skill) => {
        const dataPoint: any = { skill };
        scores.forEach((score, index) => {
          dataPoint[`candidate${index}`] = score ?? 0;
        });
        radarData.push(dataPoint);
      });

      // Build skill comparison table
      const skillComparison: any[] = [];
      skillsMap.forEach((scores, skillName) => {
        skillComparison.push({ skillName, scores });
      });

      // Calculate average scores
      const averageScores = candidatesResults.map((results) => {
        const skillBasedResults = results.filter((r) => {
          if (r.status !== 'completed' || !r.scores) return false;
          const normalized = normalizeAssessmentType(r.assessmentType);
          return skillBasedAssessmentTypes.some(type => normalizeAssessmentType(type) === normalized);
        });
        
        const allScores: number[] = [];
        skillBasedResults.forEach((result) => {
          if (result.scores && typeof result.scores === 'object') {
            Object.values(result.scores).forEach((score) => {
              if (typeof score === 'number') allScores.push(score);
            });
          }
        });
        
        return allScores.length > 0 
          ? Math.round(allScores.reduce((a, b) => a + b, 0) / allScores.length)
          : 0;
      });

      // Extract assessment-specific data
      const fitAssessments = candidatesResults.map((results) => {
        const fitResult = results.find(r => normalizeAssessmentType(r.assessmentType) === 'fit' && r.status === 'completed');
        return fitResult ? { scores: fitResult.scores, completedAt: fitResult.completedAt } : null;
      });

      const aiReadinessAssessments = candidatesResults.map((results) => {
        const aiResult = results.find(r => {
          const normalized = normalizeAssessmentType(r.assessmentType);
          return (normalized === 'ai_readiness' || normalized === 'ai-readiness') && r.status === 'completed';
        });
        return aiResult ? { scores: aiResult.scores, completedAt: aiResult.completedAt } : null;
      });

      // Prompt Architecture: Fetch evaluations for level-by-level breakdown (like admin endpoint)
      const promptArchitectureAssessments = await Promise.all(
        candidatesResults.map(async (results) => {
          const promptResult = results.find(r => 
            normalizeAssessmentType(r.assessmentType) === 'prompt_architecture' && r.status === 'completed'
          );
          
          if (!promptResult) return null;
          
          // Helper function to scale dimension scores from 0-25 to 0-20
          const scaleDimensionScore = (score: number): number => {
            return Math.round((score / 25) * 20);
          };
          
          // Try to get evaluations from database first, then fall back to session.evaluations
          let finalLevelData: any[] = [];
          
          if (promptResult.isFromAssessmentResults) {
            // Fetch evaluations from database for B2C assessment results
            const evaluations = await storage.getEvaluationsByResult(promptResult.id);
            
            // Organize evaluations by level and scale scores
            const levelData = evaluations
              .filter(e => e.status === 'completed' && e.evaluationScores)
              .map(e => {
                const scores = e.evaluationScores!;
                return {
                  level: e.level,
                  scores: {
                    clarity: scaleDimensionScore(scores.clarity),
                    structure: scaleDimensionScore(scores.structure),
                    contextRelevance: scaleDimensionScore(scores.contextRelevance),
                    creativity: scaleDimensionScore(scores.creativity),
                    iterativeImprovement: scaleDimensionScore(scores.iterativeImprovement),
                  },
                  totalScore: e.totalScore,
                  feedback: e.feedback,
                };
              })
              .sort((a, b) => a.level - b.level);
            
            finalLevelData = levelData;
          }
          
          // Fallback: Check if evaluations are stored directly on the result (B2B sessions)
          if (finalLevelData.length === 0 && promptResult.evaluations && Array.isArray(promptResult.evaluations)) {
            // Helper to normalize scores from 0-100 to 0-20 if needed
            const normalizeToTwenty = (score: number | undefined): number => {
              if (score === undefined) return 0;
              return score > 20 ? Math.round((score / 100) * 20) : score;
            };
            
            // Helper to get dimension score with legacy name fallback
            const getDimensionScore = (e: any, canonical: string, legacyNames: string[]): number => {
              if (e[canonical] !== undefined) return normalizeToTwenty(e[canonical]);
              for (const name of legacyNames) {
                if (e[name] !== undefined) return normalizeToTwenty(e[name]);
              }
              return 0;
            };
            
            finalLevelData = (promptResult.evaluations as any[])
              .filter(e => e.level !== undefined && e.totalScore !== undefined)
              .map(e => ({
                level: e.level,
                scores: {
                  clarity: getDimensionScore(e, 'clarity', ['Clarity']),
                  structure: getDimensionScore(e, 'structure', ['Structure', 'Context Setting']),
                  contextRelevance: getDimensionScore(e, 'contextRelevance', ['Context Relevance', 'Output Formatting']),
                  creativity: getDimensionScore(e, 'creativity', ['Creativity', 'Constraint Definition']),
                  iterativeImprovement: getDimensionScore(e, 'iterativeImprovement', ['Iterative Improvement']),
                },
                totalScore: e.totalScore,
                feedback: e.feedback || '',
              }))
              .sort((a, b) => a.level - b.level);
          }
          
          // If no per-level evaluations exist in the database, return null (no fallback guessing)
          if (finalLevelData.length === 0) {
            return null;
          }
          
          // Ensure all 7 levels are present, fill missing with placeholders
          const levelMap2 = new Map(finalLevelData.map((l: any) => [l.level, l]));
          const sevenLevelData2 = [1, 2, 3, 4, 5, 6, 7].map(levelNum => {
            const existingLevel = levelMap2.get(levelNum);
            if (existingLevel) return existingLevel;
            return {
              level: levelNum,
              scores: { clarity: 0, structure: 0, contextRelevance: 0, creativity: 0, iterativeImprovement: 0 },
              totalScore: 0,
              feedback: 'Not completed',
              isMissing: true,
            };
          });
          
          return {
            levels: sevenLevelData2,
            totalScore: promptResult.totalScore || 0,
            percentile: promptResult.percentile || 0,
            completedAt: promptResult.completedAt,
          };
        })
      );

      const aiqAssessments = candidatesResults.map((results) => {
        const aiqResult = results.find(r => normalizeAssessmentType(r.assessmentType) === 'aiq' && r.status === 'completed');
        return aiqResult ? { 
          totalScore: aiqResult.totalScore, 
          scores: aiqResult.scores, 
          completedAt: aiqResult.completedAt 
        } : null;
      });

      // Build a descriptive title using candidate info
      const candidateDisplayNames = candidateIds.map(id => {
        // Extract email local part if it looks like an email
        if (id.includes('@')) {
          return id.split('@')[0];
        }
        return id.length > 20 ? id.substring(0, 17) + '...' : id;
      });

      // Generate AI insights for comparison reports (2+ candidates)
      let aiInsights: string | null = null;
      if (candidateIds.length >= 2) {
        try {
          const candidateSummaries = candidateDisplayNames.map((name: string, idx: number) => {
            const fitData = fitAssessments?.[idx];
            const aiData = aiReadinessAssessments?.[idx];
            const promptData = promptArchitectureAssessments?.[idx];
            const aiqData = aiqAssessments?.[idx];
            
            return `
${name}:
- FIT Assessment: ${fitData ? 'Completed (Avg: ' + Math.round(Object.values(fitData.scores as Record<string, number>).reduce((a, b) => a + b, 0) / Object.keys(fitData.scores).length) + '%)' : 'Not completed'}
- AI Readiness: ${aiData ? 'Completed (Avg: ' + Math.round(Object.values(aiData.scores as Record<string, number>).reduce((a, b) => a + b, 0) / Object.keys(aiData.scores).length) + '%)' : 'Not completed'}
- Prompt Architecture: ${promptData ? promptData.totalScore + '%' : 'Not completed'}
- AIQ: ${aiqData ? aiqData.totalScore + '%' : 'Not completed'}`;
          }).join('\n');

          const prompt = `You are an expert HR analyst comparing multiple job candidates. Generate a concise comparative analysis.

CANDIDATES BEING COMPARED:
${candidateSummaries}

Average Scores Summary:
${candidateDisplayNames.map((name: string, i: number) => name + ': ' + (averageScores?.[i] || 'N/A') + '%').join(', ')}

Provide a brief comparative analysis (under 200 words) covering:
1. **Key Differentiators**: What sets each candidate apart
2. **Complementary Strengths**: Where candidates excel differently
3. **Hiring Consideration**: Brief recommendation based on the data

Use the candidates' actual names. Be specific and actionable.`;

          const completion = await openai.chat.completions.create({
            model: "gpt-4o",
            messages: [
              { role: "system", content: "You are an expert HR analyst specializing in candidate comparisons. Provide concise, professional insights." },
              { role: "user", content: prompt }
            ],
            max_tokens: 400,
            temperature: 0.7,
          });

          aiInsights = completion.choices[0].message.content || null;

          logAiCost({
            userId: req.user.id,
            operation: 'compare_candidates_insights',
            model: 'gpt-4o',
            promptTokens: completion.usage?.prompt_tokens || 0,
            completionTokens: completion.usage?.completion_tokens || 0,
            metadata: { candidateCount: candidateIds.length },
          }).catch(console.error);
        } catch (aiError) {
          console.error("Failed to generate AI insights for comparison:", aiError);
        }
      } else if (candidateIds.length === 1) {
        // Profile insights for individual candidate report
        try {
          const fitData = fitAssessments?.[0];
          const aiData = aiReadinessAssessments?.[0];
          const promptData = promptArchitectureAssessments?.[0];
          const aiqData = aiqAssessments?.[0];
          
          // Only generate if there's at least some assessment data
          if (fitData || aiData || promptData || aiqData) {
            const candidateName = candidateDisplayNames[0];
            
            // Calculate strengths and weaknesses
            const skills: Array<{ name: string; score: number; category: string }> = [];
            if (fitData) {
              Object.entries(fitData.scores as Record<string, number>).forEach(([name, score]) => {
                skills.push({ name, score: score as number, category: 'FIT' });
              });
            }
            if (aiData) {
              Object.entries(aiData.scores as Record<string, number>).forEach(([name, score]) => {
                skills.push({ name, score: score as number, category: 'AI Readiness' });
              });
            }
            skills.sort((a, b) => b.score - a.score);
            const strengths = skills.slice(0, 3);
            const weaknesses = skills.slice(-3).reverse();
            
            const fitAvg = fitData ? Math.round(Object.values(fitData.scores as Record<string, number>).reduce((a, b) => a + b, 0) / Object.keys(fitData.scores).length) : null;
            const aiAvg = aiData ? Math.round(Object.values(aiData.scores as Record<string, number>).reduce((a, b) => a + b, 0) / Object.keys(aiData.scores).length) : null;
            
            const prompt = `You are an expert HR analyst. Generate a comprehensive profile analysis for a job candidate based on their assessment results.

CANDIDATE: ${candidateName}

ASSESSMENT DATA:
${fitData ? 'FIT (Behavioral Traits) - Average: ' + fitAvg + '%\nIndividual Scores: ' + JSON.stringify(fitData.scores, null, 2) : 'FIT Assessment: Not completed'}

${aiData ? 'AI Readiness (Technical) - Average: ' + aiAvg + '%\nIndividual Scores: ' + JSON.stringify(aiData.scores, null, 2) : 'AI Readiness Assessment: Not completed'}

${promptData ? 'Prompt Architecture: ' + promptData.totalScore + '%' : 'Prompt Architecture: Not completed'}

${aiqData ? 'AIQ (AI Ethics): ' + aiqData.totalScore + '%' : 'AIQ Assessment: Not completed'}

HIGHEST SCORING TRAITS: ${strengths.map(s => s.name + ' (' + s.score + '%)').join(', ') || 'N/A'}

LOWEST SCORING TRAITS: ${weaknesses.map(s => s.name + ' (' + s.score + '%)').join(', ') || 'N/A'}

IMPORTANT: FIT and AI Readiness are TRAIT-BASED assessments. High scores mean the trait is STRONGLY PRESENT, not that it's "good" or "bad". Whether a high score is beneficial depends on role requirements.

Generate a structured analysis with EXACTLY these 5 sections. Use the headers exactly as shown:

**ROLE SUITABILITY**
Based on the trait profile, describe 2-3 types of roles or work environments where this candidate would excel. Be specific about role characteristics and job titles.

**OPTIMAL ENVIRONMENT**
Describe the ideal work environment, company culture, and team dynamics where this candidate would thrive. Consider factors like pace, structure, team size, and management style.

**KEY STRENGTHS**
List the top 3 standout traits and explain how they benefit the workplace. Reference specific assessment scores.

**DEVELOPMENT FOCUS**
Identify 2-3 priority areas for professional development based on lower-scoring traits. Be specific about what training, mentoring, or experiences would benefit this candidate most. Frame constructively with actionable suggestions.

**OVERALL ASSESSMENT AND RECOMMENDATION**
Provide a concise overall assessment and recommendation for hiring managers, including ideal role types, team fit, and any potential concerns to be aware of.

Keep each section concise (2-3 sentences). Use professional but accessible language.`;

            const completion = await openai.chat.completions.create({
              model: "gpt-4o",
              messages: [
                { role: "system", content: "You are an expert HR analyst specializing in candidate assessments. Provide insightful, balanced profile analyses." },
                { role: "user", content: prompt }
              ],
              max_tokens: 800,
              temperature: 0.7,
            });

            aiInsights = completion.choices[0].message.content || null;

            logAiCost({
              userId: req.user.id,
              operation: 'individual_candidate_profile_insights',
              model: 'gpt-4o',
              promptTokens: completion.usage?.prompt_tokens || 0,
              completionTokens: completion.usage?.completion_tokens || 0,
              metadata: { candidateId: candidateIds[0] },
            }).catch(console.error);
          }
        } catch (aiError) {
          console.error("Failed to generate AI insights for individual report:", aiError);
        }
      }


      const resultData = {
        radarData,
        skillComparison,
        averageScores,
        hasSkillData: radarData.length > 0,
        fitAssessments,
        aiReadinessAssessments,
        promptArchitectureAssessments,
        aiqAssessments,
        aiInsights,
        generatedAt: new Date().toISOString(),
        version: 1,
      };
      
      // Determine report type based on candidate count
      const isIndividualReport = candidateIds.length === 1;
      const reportType = isIndividualReport ? 'individual' : 'comparison';
      const reportTitle = isIndividualReport 
        ? `Individual Report: ${candidateDisplayNames[0]}`
        : candidateDisplayNames.length <= 3 
          ? `Candidate Comparison: ${candidateDisplayNames.join(', ')}`
          : `Candidate Comparison: ${candidateDisplayNames.slice(0, 2).join(', ')} +${candidateDisplayNames.length - 2} more`;

      // Save the report for future access
      const savedReport = await storage.createPartnerAnalysisReport({
        partnerId: partner.id,
        reportType: reportType,
        version: 1,
        candidateIds: candidateIds,
        title: reportTitle,
        resultData: resultData as any,
        creditsUsed: candidateIds.length,
        generatedByUserId: req.user.id,
      });

      res.json({
        ...resultData,
        cached: false,
        generatedAt: new Date().toISOString(),
        reportId: savedReport.id,
      });
    } catch (error) {
      console.error("Error comparing partner candidates:", error);
      res.status(500).json({ message: "Failed to compare candidates" });
    }
  });

  // Partner: Generate AI insights for candidate comparison (kept for backwards compatibility)
