  // Partner: Get platform averages for PDF export
  app.get("/api/partner/me/platform-averages", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      // Get partner's candidates
      const sessions = await storage.getSessionsByPartner(partner.id, 10000);
      const completedSessions = sessions.filter(s => s.status === 'completed' && !s.isTestSession);
      
      // Calculate partner-wide averages
      const allSkills: Record<string, number[]> = {};
      let totalScores: number[] = [];
      let candidateCount = 0;
      
      // Process session-based candidates
      const processedEmails = new Set<string>();
      for (const session of completedSessions) {
        const email = session.externalEmail || session.externalUserId || session.id;
        if (!processedEmails.has(email)) {
          processedEmails.add(email);
          candidateCount++;
        }
        
        if (session.scores && typeof session.scores === 'object') {
          let sessionScores: number[] = [];
          Object.entries(session.scores).forEach(([skillName, score]) => {
            if (typeof score === 'number') {
              if (!allSkills[skillName]) {
                allSkills[skillName] = [];
              }
              allSkills[skillName].push(score);
              sessionScores.push(score);
            }
          });
          
          if (sessionScores.length > 0) {
            const avg = sessionScores.reduce((a, b) => a + b, 0) / sessionScores.length;
            totalScores.push(avg);
          }
        }
      }
      
      // Calculate skill averages
      const skillAverages: Record<string, number> = {};
      Object.entries(allSkills).forEach(([skillName, scores]) => {
        if (scores.length > 0) {
          skillAverages[skillName] = Math.round(
            scores.reduce((a, b) => a + b, 0) / scores.length
          );
        }
      });
      
      // Calculate overall partner average
      const avgScoreAcrossCandidates = totalScores.length > 0
        ? Math.round(totalScores.reduce((a, b) => a + b, 0) / totalScores.length)
        : 0;
      
      res.json({
        totalCandidates: candidateCount,
        avgScoreAcrossCandidates,
        skillAverages,
      });
    } catch (error) {
      console.error("Error fetching partner platform averages:", error);
      res.status(500).json({ message: "Failed to fetch platform averages" });
    }
  });

  // Partner: Add note to candidate
  app.post("/api/partner/me/candidates/notes", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      const { userId, note } = req.body;
      if (!userId || !note) {
        return res.status(400).json({ message: "User ID and note are required" });
      }
      
      // Verify the candidate belongs to this partner by checking sessions or invitations
      const allSessions = await storage.getSessionsByPartner(partner.id, 10000);
      const candidateSession = allSessions.find(
        s => s.externalEmail === userId || s.externalUserId === userId || s.id === userId
      );
      
      // Also check partner invitations
      const invitations = await db.select()
        .from(partnerCandidateInvitations)
        .where(and(
          eq(partnerCandidateInvitations.partnerId, partner.id),
          eq(partnerCandidateInvitations.email, userId)
        ));
      
      if (!candidateSession && invitations.length === 0) {
        return res.status(404).json({ message: "Candidate not found for this partner" });
      }

      // Use partner-prefixed userId to store notes for partner candidates
      // This allows notes to be associated with the candidate while keeping partner context
      const partnerCandidateId = `partner:${partner.id}:${userId}`;
      
      const createdNote = await storage.createCandidateNote({
        userId: partnerCandidateId,
        note: note,
        createdBy: req.user.id,
      });

      res.json({
        id: createdNote.id,
        content: createdNote.note,
        createdAt: createdNote.createdAt,
      });
    } catch (error) {
      console.error("Error adding partner note:", error);
      res.status(500).json({ message: "Failed to add note" });
    }
  });

  // Partner: Get available roles (for analysis tab)
  app.get("/api/partner/me/roles", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      // Partners can access all job roles
      const roles = await storage.getAllJobRoles();
      res.json(roles);
    } catch (error) {
      console.error("Error fetching partner roles:", error);
      res.status(500).json({ message: "Failed to fetch roles" });
    }
  });

  // Partner: Get role alignment for a candidate (for analysis tab)
  app.get("/api/partner/me/role-alignment", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      const { candidateId, jobRoleId, forceRefresh } = req.query;
      
      if (!candidateId || !jobRoleId) {
        return res.status(400).json({ message: "Candidate ID and job role ID are required" });
      }

      // Verify the candidate belongs to this partner FIRST (before consuming credits)
      // SOURCE 1: Check B2B Widget/API sessions
      const allSessions = await storage.getSessionsByPartner(partner.id, 10000);
      let candidateSessions = allSessions.filter(
        s => s.externalEmail === candidateId || s.externalUserId === candidateId || s.id === candidateId
      );
      
      // SOURCE 2: Check partner invitation candidates if not found in sessions
      let isInvitedCandidate = false;
      if (candidateSessions.length === 0) {
        const partnerInvitations = await db.select()
          .from(partnerCandidateInvitations)
          .where(eq(partnerCandidateInvitations.partnerId, partner.id));
        isInvitedCandidate = partnerInvitations.some(
          inv => inv.email === candidateId || inv.externalUserId === candidateId || inv.userId === candidateId
        );
        
        if (!isInvitedCandidate) {
          return res.status(403).json({ message: "Candidate not found in your organization" });
        }
      }

      // Get role
      const role = await storage.getJobRole(jobRoleId as string);
      if (!role) {
        return res.status(404).json({ message: "Job role not found" });
      }

      let hadInvalidatedOldReport = false;

      // Check for existing cached report (unless forceRefresh is requested)
      if (forceRefresh !== 'true') {
        const existingReport = await storage.findExistingPartnerReport(
          partner.id,
          'role_fit_single',
          [candidateId as string],
          jobRoleId as string
        );
        if (existingReport) {
          const resultData = existingReport.resultData as any;
          const hasAiInsights = resultData && (resultData.promptRoleFitAnalysis || resultData.aiqRoleFitAnalysis);
          const hasOldCriticality = (resultData?.fitSkillAlignments || []).some((s: any) => s.criticality === 'important') ||
            (resultData?.aiReadinessSkillAlignments || []).some((s: any) => s.criticality === 'important');
          const hasFinalRecommendation = resultData && resultData.finalRecommendation && resultData.nextSteps;
          const hasCurrentScoring = resultData && resultData.scoringVersion >= 2;
          if (hasAiInsights && !hasOldCriticality && hasFinalRecommendation && hasCurrentScoring) {
            return res.json({
              ...resultData,
              cached: true,
              cachedAt: existingReport.createdAt,
              generatedAt: existingReport.createdAt,
              reportId: existingReport.id,
            });
          }
          if (hasOldCriticality || !hasFinalRecommendation || !hasCurrentScoring) {
            hadInvalidatedOldReport = true;
          }
        }
      }

      // Check if we have an incomplete cached report (exists but lacks AI insights)
      // In this case, skip credit consumption since the original report already charged
      // Also skip credit consumption if we just invalidated an old cached report (already paid for)
      let hasIncompleteCachedReport = false;
      if (forceRefresh !== 'true') {
        const existingReport = await storage.findExistingPartnerReport(
          partner.id,
          'role_fit_single',
          [candidateId as string],
          jobRoleId as string
        );
        if (existingReport) {
          const resultData = existingReport.resultData as any;
          hasIncompleteCachedReport = !resultData?.promptRoleFitAnalysis && !resultData?.aiqRoleFitAnalysis;
        }
      }

      // All validations passed - consume 1 credit unless regenerating incomplete cached report
      let creditResult: any = { success: true, remaining: 0, isOverage: false };
      if (!hasIncompleteCachedReport && !hadInvalidatedOldReport) {
        creditResult = await storage.consumePartnerTest(
          partner.id,
          null,
          "Single candidate role fit analysis"
        );
        
        if (!creditResult.success && !creditResult.isOverage) {
          return res.status(402).json({ 
            message: "Insufficient credits. Please purchase more credits to analyze candidates.",
            creditsRequired: 1,
            creditsRemaining: creditResult.remaining
          });
        }
      }

      // Collect all assessment results for this candidate
      const completedSessions = candidateSessions.filter(s => s.status === 'completed');

      // Calculate fit scores from session data (sessions store scores directly)
      let fitScores: Record<string, number> | null = null;
      let aiReadinessScores: Record<string, number> | null = null;
      let promptArchitectureScore: number | null = null;
      let promptArchitectureScores: Record<string, number> | null = null;
      let aiqScore: number | null = null;
      let aiqScores: Record<string, number> | null = null;

      // SOURCE 1: Check B2B sessions first
      for (const session of completedSessions) {
        if (!session.scores) continue;
        
        if (session.assessmentType === 'fit') {
          fitScores = session.scores as Record<string, number>;
        } else if (session.assessmentType === 'ai_readiness') {
          aiReadinessScores = session.scores as Record<string, number>;
        } else if (session.assessmentType === 'prompt_architecture') {
          promptArchitectureScores = session.scores as Record<string, number>;
          promptArchitectureScore = session.totalScore;
        } else if (session.assessmentType === 'aiq') {
          aiqScores = session.scores as Record<string, number>;
          aiqScore = session.totalScore;
        }
      }
      


      // Parse role requirements from requiredSkillScores JSON
      const roleRequirements = role.requiredSkillScores as {
        fitSkills?: Record<string, number>;
        aiReadinessSkills?: Record<string, number>;
        skillCriticality?: Record<string, string>;
      } | null;
      
      const fitRequiredScores = roleRequirements?.fitSkills || null;
      const aiReadinessRequiredScores = roleRequirements?.aiReadinessSkills || null;
      const skillCriticality = roleRequirements?.skillCriticality || {};

      // Nudge helper to avoid multiples of 5 in required scores (matches admin endpoint)
// Mapping from short skill names (used in required scores) to full names (stored in assessment results)
      const aiReadinessSkillMapping = {
        'AI Literacy': 'AI Literacy & Prompt Engineering',
        'Collaboration': 'Collaboration & Communication',
        'Domain Fluency': 'Data Fluency',
        'Responsible AI': 'Responsible AI & Ethical Awareness',
        'Data Fluency': 'Data Fluency',
        'Technical Fundamentals': 'Technical Fundamentals',
        'Technical Fluency': 'Technical Fundamentals',
        'Critical Thinking': 'Critical Thinking & Problem-Solving',
        'Adaptability': 'Adaptability & Continuous Learning',
        'Adaptive Learning': 'Adaptability & Continuous Learning',
        'Creativity': 'Creativity & Innovation',
        'Creative Innovation': 'Creativity & Innovation',
        'Domain Expertise': 'Domain Expertise',
      };

      // Calculate alignment
      const fitSkillAlignments = fitRequiredScores && fitScores
        ? Object.entries(fitRequiredScores).map(([skillName, requiredScore]) => {
            
            const candidateScore = fitScores![skillName] ?? null;
            const gap = candidateScore !== null ? candidateScore - requiredScore : null;
            return {
              skillName,
              candidateScore,
              requiredScore: requiredScore,
              gap,
              alignment: gap === null ? 'not_assessed' : gap >= 10 ? 'excellent' : gap >= 0 ? 'good' : gap >= -15 ? 'fair' : 'poor',
              criticality: skillCriticality[skillName] || 'standard',
              dataAvailable: candidateScore !== null,
            };
          })
        : null;

      const aiReadinessSkillAlignments = aiReadinessRequiredScores && aiReadinessScores
        ? Object.entries(aiReadinessRequiredScores).map(([skillName, requiredScore]) => {
            
            const fullSkillName = aiReadinessSkillMapping[skillName] || skillName;
            const candidateScore = aiReadinessScores![fullSkillName] ?? aiReadinessScores![skillName] ?? null;
            const gap = candidateScore !== null ? candidateScore - requiredScore : null;
            return {
              skillName: fullSkillName,
              candidateScore,
              requiredScore: requiredScore,
              gap,
              alignment: gap === null ? 'not_assessed' : gap >= 10 ? 'excellent' : gap >= 0 ? 'good' : gap >= -15 ? 'fair' : 'poor',
              criticality: skillCriticality[fullSkillName] || skillCriticality[skillName] || 'standard',
              dataAvailable: candidateScore !== null,
            };
          })
        : null;

      // Calculate overall fit score
      const allAlignments = [
        ...(fitSkillAlignments || []),
        ...(aiReadinessSkillAlignments || []),
      ];
      
      const scoredAlignments = allAlignments.filter(a => a.candidateScore !== null);
      
      // Weighted scoring with critical gap penalty (matches admin + multi-candidate logic)
      let overallFit: number | null = null;
      if (scoredAlignments.length > 0) {
        const getSkillWeightLocal = (crit: string): number => {
          if (crit === 'critical') return 2.0;
          return 1.0;
        };
        let weightedTotal = 0;
        let weightSum = 0;
        let criticalGaps = 0;
        let totalCriticalSkills = 0;
        let assessedCriticalSkills = 0;
        
        allAlignments.forEach(skill => {
          const isCritical = skill.criticality === 'critical';
          if (isCritical) totalCriticalSkills++;
          
          if (skill.dataAvailable && skill.candidateScore !== null) {
            const weight = getSkillWeightLocal(skill.criticality || 'standard');
            if (isCritical) assessedCriticalSkills++;
            
            const matchPercent = skill.candidateScore >= skill.requiredScore
              ? 100
              : (skill.candidateScore / skill.requiredScore) * 100;
            
            weightedTotal += matchPercent * weight;
            weightSum += weight;
            
            if (isCritical && skill.candidateScore < skill.requiredScore) {
              criticalGaps++;
            }
          }
        });
        
        overallFit = weightSum > 0 ? weightedTotal / weightSum : 0;
        
        // Unassessed critical skills count as gaps too
        const unassessedCriticalSkills = totalCriticalSkills - assessedCriticalSkills;
        const totalCriticalGaps = criticalGaps + unassessedCriticalSkills;
        
        if (totalCriticalGaps > 0 && totalCriticalSkills > 0) {
          const criticalPenalty = totalCriticalGaps * 0.12;
          overallFit = overallFit * (1 - Math.min(criticalPenalty, 0.5));
          overallFit = Math.min(overallFit, 74);
        }
        
        overallFit = Math.round(overallFit);
      }

      // Determine strengths and gaps
      const strengths = scoredAlignments
        .filter(a => (a.gap || 0) >= 10)
        .map(a => a.skillName)
        .slice(0, 3);
      
      const gaps = scoredAlignments
        .filter(a => (a.gap || 0) < -10)
        .map(a => a.skillName)
        .slice(0, 3);

      // Generate Prompt and AIQ Role Fit analyses (single-loading UX)
      let promptRoleFitAnalysis: string | null = null;
      let aiqRoleFitAnalysis: string | null = null;
      
      try {
        // Get assessment data from partner's B2B sessions only
        const promptSession = candidateSessions.find(s => s.assessmentType === 'prompt_architecture' && s.status === 'completed');
        const aiqSession = candidateSessions.find(s => s.assessmentType === 'aiq' && s.status === 'completed');
        
        // Use invitation name or extract from email
        const invitations = await storage.getPartnerCandidateInvitations(partner.id);
        const candidateInvitation = invitations.find(inv => 
          inv.email === candidateId || inv.externalUserId === candidateId
        );
        const candidateName = candidateInvitation?.name || candidateSessions[0]?.externalEmail?.split('@')[0] || candidateId;

          // Generate Prompt Role Fit analysis
          if (promptArchitectureScore !== null || promptSession) {
            let promptScore = promptArchitectureScore !== null ? `${promptArchitectureScore}%` : (promptSession ? `${promptSession.totalScore || 0}%` : 'No data available');
            let promptLevels = '';
            if (promptSession) {
              const levels = (promptSession as any).levels || [];
              if (levels.length > 0) {
                promptLevels = levels.map((l: any) => 
                  `Level ${l.level}: ${l.passed ? 'Passed' : 'Failed'}${l.scores ? ` (Clarity: ${l.scores.clarity}%, Structure: ${l.scores.structure}%, Context: ${l.scores.contextRelevance}%, Creativity: ${l.scores.creativity}%, Iterative: ${l.scores.iterativeImprovement}%)` : ''}`
                ).join('\n');
              }
            } else if (promptArchitectureScores) {
              // Use session scores for B2B candidates
              const scoreKeys = Object.keys(promptArchitectureScores);
              if (scoreKeys.length > 0) {
                promptLevels = scoreKeys.map(key => `${key}: ${(promptArchitectureScores as Record<string, number>)[key]}%`).join('\n');
              }
            }

            
            const promptAnalysisPrompt = `You are an expert HR analyst evaluating how a candidate's prompt engineering skills align with a specific job role.

CANDIDATE: ${candidateName}
JOB ROLE: ${role.name}
${role.description ? `ROLE DESCRIPTION: ${role.description}` : ''}

PROMPT ARCHITECTURE ASSESSMENT RESULTS:
- Overall Score: ${promptScore}
${promptLevels ? `- Level Details:\n${promptLevels}` : '- No detailed level data available'}

In 1-2 short paragraphs (max 120 words total), address ONLY:
1. How and why this specific role requires prompt engineering / AI interaction skills
2. Whether the candidate's score and skill profile meet those requirements, and key risks if they don't

Be direct and specific to the role. No general background on prompt engineering.`;
            const promptResponse = await openai.chat.completions.create({
              model: 'gpt-4o',
              messages: [{ role: 'user', content: promptAnalysisPrompt }],
              max_tokens: 400,
              temperature: 0.7,
            });
            promptRoleFitAnalysis = promptResponse.choices[0]?.message?.content || null;
            
            logAiCost({
              operationType: AI_USAGE_OPERATION_TYPES.PROMPT_ROLE_FIT,
              model: "gpt-4o",
              usage: extractUsage(promptResponse),
              userId: candidateId as string,
              partnerId: partner.id,
              metadata: { roleTitle: role.name },
            }).catch(console.error);
          }

          // Generate AIQ Role Fit analysis
          if (aiqScore !== null || aiqSession) {
            let aiqScoreStr = aiqScore !== null ? `${aiqScore}%` : (aiqSession ? `${aiqSession.totalScore || 0}%` : 'No data available');
            let aiqBand = '';
            if (aiqScore !== null || aiqSession) {
              const score = aiqScore !== null ? aiqScore : (aiqSession?.totalScore || 0);
              if (score >= 80) aiqBand = 'Exemplary (80-100%): Strong ethical foundation with nuanced understanding of AI implications';
              else if (score >= 60) aiqBand = 'Strong (60-79%): Solid grasp of AI ethics with some areas for deeper exploration';
              else if (score >= 40) aiqBand = 'Developing (40-59%): Foundational understanding with room for growth';
              else if (score >= 20) aiqBand = 'Gaps Identified (20-39%): Requires focused development on AI ethical principles';
              else aiqBand = 'Critical Concerns (0-19%): Fundamental misalignment with ethical AI principles';
            }

            const aiqAnalysisPrompt = `You are an expert HR analyst evaluating how a candidate's ethical AI stance (AIQ - Algorithmic Integrity Quotient) aligns with a specific job role.

CANDIDATE: ${candidateName}
JOB ROLE: ${role.name}
${role.description ? `ROLE DESCRIPTION: ${role.description}` : ''}

AIQ ASSESSMENT RESULTS:
- Overall Score: ${aiqScoreStr}
${aiqBand ? `- Performance Band: ${aiqBand}` : ''}

In 1-2 short paragraphs (max 120 words total), address ONLY:
1. How and why this specific role requires ethical AI understanding and responsible AI practices
2. Whether the candidate's AIQ score meets those requirements, and key risks from any ethical blind spots

Be direct and specific to the role. No general background on AI ethics.`;
            const aiqResponse = await openai.chat.completions.create({
              model: 'gpt-4o',
              messages: [{ role: 'user', content: aiqAnalysisPrompt }],
              max_tokens: 400,
              temperature: 0.7,
            });
            aiqRoleFitAnalysis = aiqResponse.choices[0]?.message?.content || null;
            
            logAiCost({
              operationType: AI_USAGE_OPERATION_TYPES.AIQ_ROLE_FIT,
              model: "gpt-4o",
              usage: extractUsage(aiqResponse),
              userId: candidateId as string,
              partnerId: partner.id,
              metadata: { roleTitle: role.name },
            }).catch(console.error);
          }
      } catch (aiError) {
        console.error("Failed to generate Prompt/AIQ role fit analyses:", aiError);
      }

      // Calculate cohort benchmarks from all partner sessions
      const cohortBenchmarks: {
        overall?: { percentile: number; totalCandidates: number; position: string };
        fit?: { percentile: number; totalCandidates: number; skillCount: number; avgScore: number };
        ai_readiness?: { percentile: number; totalCandidates: number; skillCount: number; avgScore: number };
        prompt_architecture?: { percentile: number; totalCandidates: number; avgScore: number };
        aiq?: { percentile: number; totalCandidates: number; avgScore: number };
      } = {};

      try {
        // Get all completed sessions for this partner to calculate cohort benchmarks
        const allPartnerSessions = await storage.getSessionsByPartner(partner.id, 10000);
        const completedPartnerSessions = allPartnerSessions.filter(s => s.status === 'completed' && s.scores);
        
        // Group sessions by assessment type
        const sessionsByType: Record<string, typeof completedPartnerSessions> = {};
        completedPartnerSessions.forEach(session => {
          if (!sessionsByType[session.assessmentType]) {
            sessionsByType[session.assessmentType] = [];
          }
          sessionsByType[session.assessmentType].push(session);
        });

        const calculatePercentile = (score: number, allScores: number[]): number => {
          const sorted = [...allScores].sort((a, b) => a - b);
          const belowCount = sorted.filter(s => s < score).length;
          return Math.round((belowCount / Math.max(sorted.length - 1, 1)) * 100);
        };

        // FIT benchmarks
        const fitSessions = sessionsByType['fit'] || [];
        if (fitSessions.length >= 5 && fitScores) {
          const fitAverages = fitSessions.map(s => {
            const scores = Object.values(s.scores as Record<string, number>);
            return scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;
          });
          const candidateFitAvg = Object.keys(fitScores).length > 0
            ? Object.values(fitScores).reduce((a, b) => a + b, 0) / Object.keys(fitScores).length
            : 0;
          if (candidateFitAvg > 0) {
            cohortBenchmarks.fit = {
              percentile: calculatePercentile(candidateFitAvg, fitAverages),
              totalCandidates: fitSessions.length,
              skillCount: Object.keys(fitScores).length,
              avgScore: Math.round(candidateFitAvg)
            };
          }
        }

        // AI Readiness benchmarks
        const aiSessions = sessionsByType['ai_readiness'] || [];
        if (aiSessions.length >= 5 && aiReadinessScores) {
          const aiAverages = aiSessions.map(s => {
            const scores = Object.values(s.scores as Record<string, number>);
            return scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;
          });
          const candidateAiAvg = Object.keys(aiReadinessScores).length > 0
            ? Object.values(aiReadinessScores).reduce((a, b) => a + b, 0) / Object.keys(aiReadinessScores).length
            : 0;
          if (candidateAiAvg > 0) {
            cohortBenchmarks.ai_readiness = {
              percentile: calculatePercentile(candidateAiAvg, aiAverages),
              totalCandidates: aiSessions.length,
              skillCount: Object.keys(aiReadinessScores).length,
              avgScore: Math.round(candidateAiAvg)
            };
          }
        }

        // Prompt Architecture benchmarks
        const paSessions = sessionsByType['prompt_architecture'] || [];
        if (paSessions.length >= 5 && promptArchitectureScore !== null) {
          const paScores = paSessions.map(s => s.totalScore || 0);
          cohortBenchmarks.prompt_architecture = {
            percentile: calculatePercentile(promptArchitectureScore, paScores),
            totalCandidates: paSessions.length,
            avgScore: promptArchitectureScore
          };
        }

        // AIQ benchmarks
        const aiqSessions = sessionsByType['aiq'] || [];
        if (aiqSessions.length >= 5 && aiqScore !== null) {
          const aiqScoresArray = aiqSessions.map(s => s.totalScore || 0);
          cohortBenchmarks.aiq = {
            percentile: calculatePercentile(aiqScore, aiqScoresArray),
            totalCandidates: aiqSessions.length,
            avgScore: aiqScore
          };
        }

        // Calculate overall position
        if (Object.keys(cohortBenchmarks).length > 0) {
          const uniqueCandidates = new Set(completedPartnerSessions.map(s => s.externalEmail || s.externalUserId || s.id));
          const candidateOverallScores: { id: string; avgScore: number }[] = [];
          
          uniqueCandidates.forEach(candId => {
            const candSessions = completedPartnerSessions.filter(s => 
              (s.externalEmail || s.externalUserId || s.id) === candId
            );
            if (candSessions.length > 0) {
              const avgScores = candSessions.map(s => {
                const scores = Object.values(s.scores as Record<string, number>);
                return scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : s.totalScore || 0;
              });
              candidateOverallScores.push({
                id: candId,
                avgScore: avgScores.reduce((a, b) => a + b, 0) / avgScores.length
              });
            }
          });

          candidateOverallScores.sort((a, b) => b.avgScore - a.avgScore);
          
          const thisCandidateAvg = overallFit || 0;
          let thisIndex = candidateOverallScores.findIndex(c => 
            Math.abs(c.avgScore - thisCandidateAvg) < 1
          );
          if (thisIndex === -1) thisIndex = candidateOverallScores.length;
          
          if (candidateOverallScores.length >= 5) {
            const actualPosition = thisIndex + 1;
            const totalCandidates = candidateOverallScores.length;
            const belowCount = totalCandidates - actualPosition;
            const overallPercentile = Math.round((belowCount / Math.max(totalCandidates - 1, 1)) * 100);
            
            const getOrdinalSuffix = (n: number): string => {
              const s = ['th', 'st', 'nd', 'rd'];
              const v = n % 100;
              return n + (s[(v - 20) % 10] || s[v] || s[0]);
            };
            
            cohortBenchmarks.overall = {
              percentile: overallPercentile,
              totalCandidates: totalCandidates,
              position: getOrdinalSuffix(actualPosition)
            };
          }
        }
      } catch (cohortError) {
        console.error('Failed to calculate cohort benchmarks:', cohortError);
      }

      // Calculate role flexibility - find alternative roles this candidate fits
      const roleFlexibilityResults: Array<{
        roleId: string;
        roleName: string;
        fitScore: number;
        rawFitScore: number;
        roleSimilarity: number;
        coveragePercent: number;
        coverageLabel: 'High' | 'Medium' | 'Limited';
        missingCriticalSkills: string[];
        description: string;
      }> = [];

      try {
        const allRoles = await storage.getAllJobRoles();
        const targetRoleSkills = role.requiredScores as Record<string, number> || {};

        for (const altRole of allRoles) {
          if (altRole.id === role.id) continue; // Skip target role
          
          const altRequiredScores = altRole.requiredScores as Record<string, number> || {};
          if (Object.keys(altRequiredScores).length === 0) continue;
          
          // Calculate candidate's fit to alternative role
          let fitSum = 0;
          let fitCount = 0;
          const missingCritical: string[] = [];
          
          for (const [skill, required] of Object.entries(altRequiredScores)) {
            const candidateScore = fitScores?.[skill] || aiReadinessScores?.[skill] || null;
            if (candidateScore !== null) {
              fitSum += Math.min(100, (candidateScore / required) * 100);
              fitCount++;
            }
          }
          
          if (fitCount === 0) continue;
          
          const rawFitScore = Math.round(fitSum / fitCount);
          
          // Calculate role similarity (how similar is this role to target role)
          const targetSkillSet = new Set(Object.keys(targetRoleSkills));
          const altSkillSet = new Set(Object.keys(altRequiredScores));
          const intersection = [...targetSkillSet].filter(s => altSkillSet.has(s));
          const union = new Set([...targetSkillSet, ...altSkillSet]);
          const roleSimilarity = union.size > 0 ? Math.round((intersection.length / union.size) * 100) : 0;
          
          // Combined score weights role similarity and candidate fit
          const fitScore = Math.round((roleSimilarity * 0.3) + (rawFitScore * 0.7));
          
          const coveragePercent = Math.round((fitCount / Object.keys(altRequiredScores).length) * 100);
          const coverageLabel = coveragePercent >= 70 ? 'High' : coveragePercent >= 40 ? 'Medium' : 'Limited';
          
          if (fitScore >= 50) { // Only include reasonably good fits
            roleFlexibilityResults.push({
              roleId: altRole.id,
              roleName: altRole.name,
              fitScore,
              rawFitScore,
              roleSimilarity,
              coveragePercent,
              coverageLabel,
              missingCriticalSkills: missingCritical,
              description: altRole.description || ''
            });
          }
        }
        
        roleFlexibilityResults.sort((a, b) => b.fitScore - a.fitScore);
      } catch (roleFlexError) {
        console.error('Failed to calculate role flexibility:', roleFlexError);
      }

      const topAlternativeRoles = roleFlexibilityResults.slice(0, 5);

      // Generate Final Recommendation
      let finalRecommendation = '';
      
      // Critical Skills Analysis
      const criticalGapSkills = scoredAlignments
        .filter(a => a.criticality === 'critical' && (a.gap || 0) < 0)
        .sort((a, b) => (a.gap || 0) - (b.gap || 0));
      const criticalStrengthSkills = scoredAlignments
        .filter(a => (a.gap || 0) >= 10)
        .sort((a, b) => (b.gap || 0) - (a.gap || 0));
      
      if (criticalGapSkills.length > 0 || criticalStrengthSkills.length > 0) {
        finalRecommendation += 'Critical Skills Analysis:\n';
        if (criticalStrengthSkills.length > 0) {
          finalRecommendation += `The candidate demonstrates notable strength in ${criticalStrengthSkills.slice(0, 3).map(s => s.skillName).join(', ')}, exceeding role requirements in these areas. `;
        }
        if (criticalGapSkills.length > 0) {
          finalRecommendation += `However, there are gaps in ${criticalGapSkills.slice(0, 3).map(s => s.skillName).join(', ')} that require attention, as these are designated as critical competencies for this role.`;
        }
      } else {
        finalRecommendation += 'Critical Skills Analysis:\n';
        finalRecommendation += `The candidate's skill profile shows ${(overallFit || 0) >= 70 ? 'solid' : 'moderate'} alignment across the assessed competencies for the ${role?.name || 'target'} role.`;
      }

      // Cohort Context
      const overallCohort = cohortBenchmarks?.overall;
      if (overallCohort) {
        finalRecommendation += '\n\nCohort Context:\n';
        const percentile = overallCohort.percentile;
        if (percentile >= 75) {
          finalRecommendation += `This candidate ranks in the top quartile (${percentile}th percentile) compared to ${overallCohort.totalCandidates} other candidates assessed for this role, indicating above-average performance relative to the talent pool.`;
        } else if (percentile >= 50) {
          finalRecommendation += `This candidate performs at or above the median (${percentile}th percentile) compared to ${overallCohort.totalCandidates} other candidates assessed for this role.`;
        } else if (percentile >= 25) {
          finalRecommendation += `This candidate ranks in the ${percentile}th percentile compared to ${overallCohort.totalCandidates} other candidates, performing below the median of the talent pool.`;
        } else {
          finalRecommendation += `This candidate ranks in the lower quartile (${percentile}th percentile) compared to ${overallCohort.totalCandidates} other assessed candidates for this role.`;
        }
      }
      
      // Hiring Recommendation
      finalRecommendation += '\n\nHiring Recommendation:\n';
      if ((overallFit || 0) >= 85) {
        finalRecommendation += `Strongly recommend advancing to final interview stages. This candidate shows readiness to contribute immediately with minimal ramp-up time. Their skill profile aligns well with role requirements and they would likely be a valuable addition to the team.`;
      } else if ((overallFit || 0) >= 70) {
        finalRecommendation += `Recommend advancing with targeted interview focus on development areas. This candidate meets most key requirements and demonstrates good potential. With appropriate onboarding support in identified gap areas, they could become a strong contributor.`;
      } else if ((overallFit || 0) >= 55) {
        finalRecommendation += `Consider for advancement if comprehensive training resources are available. This candidate shows promise in certain competencies but would require significant development in key areas. Best suited for organizations with robust mentorship programs or roles with extended ramp-up periods.`;
      } else {
        finalRecommendation += `Recommend exploring alternative roles or deferring this candidacy. Significant skill gaps across multiple required competencies suggest this may not be an optimal match at this time. Consider entry-level positions or roles with different skill requirements that better align with current capabilities.`;
      }
      
      // Alternative Role Insight
      if (topAlternativeRoles.length > 0) {
        const betterFits = topAlternativeRoles.filter(r => r.fitScore > (overallFit || 0));
        if (betterFits.length > 0) {
          const bestAlt = betterFits[0];
          finalRecommendation += `

Alternative Role Insight:
Based on skill alignment analysis, this candidate may show stronger fit for the ${bestAlt.roleName} role (${bestAlt.fitScore}/100 fit score). Consider evaluating for this alternative if the primary role is not an ideal match.`;
        }
      }

      // Generate Recommended Next Steps
      const missingAssessmentsList = [
        ...(fitScores ? [] : ['FIT Assessment']),
        ...(aiReadinessScores ? [] : ['AI Readiness Assessment']),
        ...(promptArchitectureScore !== null ? [] : ['Prompt Architecture']),
        ...(aiqScore !== null ? [] : ['AIQ Assessment']),
      ];
      const assessmentCompletionStep = missingAssessmentsList.length > 0
        ? [`Have candidate complete ${missingAssessmentsList.join(' and ')} assessment${missingAssessmentsList.length > 1 ? 's' : ''} for a complete capability picture`]
        : [];
      
      const recGapNames = criticalGapSkills.map(s => s.skillName).slice(0, 3);
      const recStrengthNames = strengths.slice(0, 3);
      
      const nextSteps = [
        ...assessmentCompletionStep,
        ...((overallFit || 0) >= 70 
          ? [
              `Conduct a structured technical interview focusing on the candidate's practical application of ${recStrengthNames.length > 0 ? recStrengthNames.join(', ') : 'their core competencies'}. Use scenario-based questions to validate real-world capability beyond assessment scores.`,
              'Schedule a behavioral interview to explore team dynamics, leadership potential, and cultural alignment. Pay attention to how they approach collaboration and conflict resolution in cross-functional settings.',
              "Perform a team composition analysis to understand how this candidate's strengths complement existing team capabilities and identify potential synergies or overlaps with current team members.",
              criticalGapSkills.length > 0
                ? `Design a targeted 30-60-90 day development plan addressing identified gaps in ${recGapNames.join(' and ')}. Include specific training resources, mentorship pairing, and measurable milestones.`
                : "Prepare an onboarding acceleration plan that leverages the candidate's strong skill alignment to achieve rapid time-to-productivity, with clear 30-60-90 day milestones.",
              `Request professional references with specific emphasis on ${recStrengthNames.length > 0 ? recStrengthNames[0] : 'their primary strengths'} and ability to deliver results in fast-paced, evolving environments.`,
              `Advance to final decision stage — the candidate's overall alignment score of ${overallFit}/100 indicates strong readiness for the role.`
            ]
          : [
              `Schedule a combined technical and behavioral screening interview. Focus on exploring the candidate's approach to ${recGapNames.length > 0 ? recGapNames.join(' and ') : 'development areas'} through practical scenarios and case studies.`,
              "Conduct a skills gap assessment to determine the candidate's learning velocity and potential for rapid skill acquisition in areas where they currently score below requirements.",
              'Evaluate team fit through a collaborative exercise or shadow session to understand how the candidate would integrate with existing team dynamics and workflows.',
              `Create a comprehensive development roadmap if proceeding — identify specific training programs, certification paths, and mentorship opportunities to bridge the ${criticalGapSkills.length} identified skill gap${criticalGapSkills.length !== 1 ? 's' : ''}.`,
              "Consider alternative roles within the organization that better align with the candidate's current skill profile. The Role Flexibility Analysis in this report identifies potential matches.",
              'If proceeding with this role, ensure robust onboarding support is available including extended ramp-up periods, dedicated mentorship, and regular performance check-ins during the first 90 days.'
            ])
      ];

      const resultData = {
        overallFit,
        fitSkillAlignments,
        aiReadinessSkillAlignments,
        promptArchitectureScore,
        aiqScore,
        promptRoleFitAnalysis,
        aiqRoleFitAnalysis,
        strengths,
        gaps,
        finalRecommendation,
        nextSteps,
        cohortBenchmarks: Object.keys(cohortBenchmarks).length > 0 ? cohortBenchmarks : null,
        roleFlexibility: topAlternativeRoles,
        dataCoverage: {
          percentage: Math.round((scoredAlignments.length / allAlignments.length) * 100) || 0,
          assessedSkillCount: scoredAlignments.length,
          totalRequiredSkills: allAlignments.length,
          missingAssessments: [
            ...(fitScores ? [] : ['FIT Assessment']),
            ...(aiReadinessScores ? [] : ['AI Readiness Assessment']),
            ...(promptArchitectureScore !== null ? [] : ['Prompt Architecture']),
            ...(aiqScore !== null ? [] : ['AIQ Assessment']),
          ],
          hasSufficientData: scoredAlignments.length >= 3,
        },
        generatedAt: new Date().toISOString(),
        version: 1,
        scoringVersion: 2,
      };

      // Get candidate display name from session data or use candidateId
      const candidateDisplayName = candidateSessions.length > 0 
        ? candidateSessions[0].externalEmail || candidateSessions[0].externalUserId || candidateId
        : candidateId;

      // Save the report for future access
      const savedReport = await storage.createPartnerAnalysisReport({
        partnerId: partner.id,
        reportType: 'role_fit_single',
        version: 1,
        candidateIds: [candidateId as string],
        roleId: jobRoleId as string,
        title: `Role Fit: ${candidateDisplayName} for ${role.title}`,
        resultData: resultData as any,
        creditsUsed: 1,
        generatedByUserId: req.user.id,
      });

      res.json({
        ...resultData,
        cached: false,
        generatedAt: new Date().toISOString(),
        reportId: savedReport.id,
      });
    } catch (error) {
      console.error("Error fetching partner role alignment:", error);
      res.status(500).json({ message: "Failed to fetch role alignment" });
    }
  });

  // Partner: Trigger role alignment analysis (POST)
  app.post("/api/partner/me/role-alignment", isAuthenticated, async (req: any, res) => {
    try {
      const partnerData = await getPartnerForUser(req.user.id);
      const partner = partnerData?.partner;
      if (!partner) {
        return res.status(404).json({ message: "No partner account found" });
      }
      
      const { candidateId, jobRoleId } = req.body;
      
      if (!candidateId || !jobRoleId) {
        return res.status(400).json({ message: "Candidate ID and job role ID are required" });
      }

      // Verify the candidate belongs to this partner
      // SOURCE 1: Check B2B Widget/API sessions
      const allSessions = await storage.getSessionsByPartner(partner.id, 10000);
      const candidateSessions = allSessions.filter(
        s => s.externalEmail === candidateId || s.externalUserId === candidateId || s.id === candidateId
      );
      
      // SOURCE 2: Check partner invitation candidates if not found in sessions
      if (candidateSessions.length === 0) {
        const partnerInvitations = await db.select()
          .from(partnerCandidateInvitations)
          .where(eq(partnerCandidateInvitations.partnerId, partner.id));
        const isInvitedCandidate = partnerInvitations.some(
          inv => inv.email === candidateId || inv.externalUserId === candidateId || inv.userId === candidateId
        );
        
        if (!isInvitedCandidate) {
          return res.status(403).json({ message: "Candidate not found in your organization" });
        }
      }

      // For now, redirect to the GET endpoint logic (no AI generation for partners)
      // This allows the frontend to use the same mutation pattern
      const url = new URL(req.protocol + '://' + req.get('host') + '/api/partner/me/role-alignment');
      url.searchParams.set('candidateId', candidateId);
      url.searchParams.set('jobRoleId', jobRoleId);
      
      return res.redirect(307, url.pathname + url.search);
    } catch (error) {
      console.error("Error triggering partner role alignment:", error);
      res.status(500).json({ message: "Failed to analyze role alignment" });
    }
  });

