  // ==================== HEALTH MONITORING API ====================

  // Super Admin: Get system health checks with severity
  app.get("/api/admin/health/checks", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      if (user?.role !== 'super_admin') {
        return res.status(403).json({ message: "Forbidden: Super admin access required" });
      }
      
      const checks: Array<{
        name: string;
        status: 'healthy' | 'degraded' | 'unhealthy';
        severity: 'info' | 'warning' | 'error' | 'critical';
        message: string;
        latencyMs?: number;
        lastChecked: Date;
      }> = [];
      
      // Database health check
      const dbStart = Date.now();
      try {
        await db.execute(sql`SELECT 1`);
        const dbLatency = Date.now() - dbStart;
        checks.push({
          name: 'Database',
          status: dbLatency < 100 ? 'healthy' : dbLatency < 500 ? 'degraded' : 'unhealthy',
          severity: dbLatency < 100 ? 'info' : dbLatency < 500 ? 'warning' : 'critical',
          message: `Connection ${dbLatency < 100 ? 'healthy' : dbLatency < 500 ? 'slow' : 'critically slow'}`,
          latencyMs: dbLatency,
          lastChecked: new Date()
        });
      } catch (e) {
        checks.push({
          name: 'Database',
          status: 'unhealthy',
          severity: 'critical',
          message: 'Database connection failed',
          lastChecked: new Date()
        });
      }
      
      // OpenAI API health check
      const openaiStart = Date.now();
      try {
        // Just check if openai client is available without making a request
        if (process.env.OPENAI_API_KEY) {
          checks.push({
            name: 'OpenAI API',
            status: 'healthy',
            severity: 'info',
            message: 'API key configured',
            latencyMs: Date.now() - openaiStart,
            lastChecked: new Date()
          });
        } else {
          checks.push({
            name: 'OpenAI API',
            status: 'unhealthy',
            severity: 'critical',
            message: 'API key not configured',
            lastChecked: new Date()
          });
        }
      } catch (e) {
        checks.push({
          name: 'OpenAI API',
          status: 'degraded',
          severity: 'warning',
          message: 'Check failed',
          lastChecked: new Date()
        });
      }
      
      // Stripe health check
      try {
        if (process.env.STRIPE_SECRET_KEY) {
          checks.push({
            name: 'Stripe',
            status: 'healthy',
            severity: 'info',
            message: 'API key configured',
            lastChecked: new Date()
          });
        } else {
          checks.push({
            name: 'Stripe',
            status: 'unhealthy',
            severity: 'critical',
            message: 'API key not configured',
            lastChecked: new Date()
          });
        }
      } catch (e) {
        checks.push({
          name: 'Stripe',
          status: 'degraded',
          severity: 'warning',
          message: 'Check failed',
          lastChecked: new Date()
        });
      }
      
      // Email service health check
      try {
        if (process.env.GMAIL_USER && process.env.GMAIL_APP_PASSWORD) {
          checks.push({
            name: 'Email Service',
            status: 'healthy',
            severity: 'info',
            message: 'Credentials configured',
            lastChecked: new Date()
          });
        } else {
          checks.push({
            name: 'Email Service',
            status: 'unhealthy',
            severity: 'error',
            message: 'Credentials missing',
            lastChecked: new Date()
          });
        }
      } catch (e) {
        checks.push({
          name: 'Email Service',
          status: 'degraded',
          severity: 'warning',
          message: 'Check failed',
          lastChecked: new Date()
        });
      }
      
      // Memory usage check - use RSS (Resident Set Size) for total process memory
      const memUsage = process.memoryUsage();
      const rssMB = Math.round(memUsage.rss / 1024 / 1024);
      const heapUsedMB = Math.round(memUsage.heapUsed / 1024 / 1024);
      
      // Thresholds based on absolute memory usage (typical for Node.js apps)
      // < 256MB = healthy, 256-512MB = warning, > 512MB = critical
      checks.push({
        name: 'Memory',
        status: rssMB < 256 ? 'healthy' : rssMB < 512 ? 'degraded' : 'unhealthy',
        severity: rssMB < 256 ? 'info' : rssMB < 512 ? 'warning' : 'critical',
        message: `${rssMB}MB RSS (${heapUsedMB}MB heap)`,
        lastChecked: new Date()
      });
      
      // Process uptime check
      const uptimeHours = Math.round(process.uptime() / 3600);
      checks.push({
        name: 'Process Uptime',
        status: 'healthy',
        severity: 'info',
        message: `Running for ${uptimeHours}h`,
        lastChecked: new Date()
      });
      
      res.json(checks);
    } catch (error) {
      console.error("Error fetching health checks:", error);
      res.status(500).json({ message: "Failed to fetch health checks" });
    }
  });

  // Super Admin: Get API latency metrics with severity
  app.get("/api/admin/health/latency", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      if (user?.role !== 'super_admin') {
        return res.status(403).json({ message: "Forbidden: Super admin access required" });
      }
      
      const latencyMetrics: Array<{
        endpoint: string;
        category: string;
        avgLatencyMs: number;
        p95LatencyMs: number;
        requestCount: number;
        severity: 'info' | 'warning' | 'error' | 'critical';
        lastMeasured: Date;
      }> = [];
      
      // Helper function to measure latency
      const measureLatency = async (
        name: string, 
        category: string, 
        fn: () => Promise<any>,
        thresholds: { info: number; warning: number; error: number } = { info: 100, warning: 300, error: 1000 }
      ) => {
        const latencies: number[] = [];
        for (let i = 0; i < 3; i++) {
          const start = Date.now();
          try {
            await fn();
            latencies.push(Date.now() - start);
          } catch {
            latencies.push(9999);
          }
        }
        
        const avgLatency = Math.round(latencies.reduce((a, b) => a + b, 0) / latencies.length);
        const sortedLatencies = [...latencies].sort((a, b) => a - b);
        const p95Latency = Math.round(sortedLatencies[Math.floor(sortedLatencies.length * 0.95)] || avgLatency);
        
        latencyMetrics.push({
          endpoint: name,
          category,
          avgLatencyMs: avgLatency,
          p95LatencyMs: p95Latency,
          requestCount: 3,
          severity: avgLatency < thresholds.info ? 'info' : avgLatency < thresholds.warning ? 'warning' : avgLatency < thresholds.error ? 'error' : 'critical',
          lastMeasured: new Date()
        });
      };
      
      // Run all measurements in parallel for speed
      await Promise.all([
        // Database endpoints
        measureLatency('Database Query (users)', 'Database', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM users`),
          { info: 50, warning: 150, error: 500 }
        ),
        measureLatency('Database Query (results)', 'Database', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM assessment_results`),
          { info: 50, warning: 150, error: 500 }
        ),
        measureLatency('Database Query (purchases)', 'Database', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM purchases`),
          { info: 50, warning: 150, error: 500 }
        ),
        measureLatency('Database Query (sessions)', 'Database', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM assessment_sessions`),
          { info: 50, warning: 150, error: 500 }
        ),
        
        // Auth endpoints
        measureLatency('/api/user', 'Auth', 
          async () => await storage.getUser(userId)
        ),
        measureLatency('/api/auth/session', 'Auth', 
          async () => await db.execute(sql`SELECT 1`)
        ),
        
        // Core API endpoints
        measureLatency('/api/assessments', 'Core API', 
          async () => await db.select().from(assessmentResults).limit(1)
        ),
        measureLatency('/api/purchases', 'Core API', 
          async () => await db.select().from(purchases).limit(1)
        ),
        
        // Admin endpoints
        measureLatency('/api/admin/candidates', 'Admin', 
          async () => await db.select().from(users).limit(10)
        ),
        measureLatency('/api/admin/analytics', 'Admin', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM users WHERE role = 'user'`)
        ),
        measureLatency('/api/admin/billing/stats', 'Admin', 
          async () => await db.execute(sql`SELECT COUNT(*) FROM purchases WHERE status = 'completed'`)
        ),
        
        // Partner API endpoints
        measureLatency('/api/partner/sessions', 'Partner API', 
          async () => await db.select().from(assessmentSessions).limit(1)
        ),
        measureLatency('/api/partner/usage', 'Partner API', 
          async () => await db.select().from(partnerMonthlyUsage).limit(1)
        ),
        
        // AI Integrations
        measureLatency('OpenAI API (models list)', 'AI Integration', 
          async () => {
            if (!process.env.OPENAI_API_KEY) throw new Error('No API key');
            await openai.models.list();
          },
          { info: 500, warning: 1500, error: 5000 }
        ),
        measureLatency('OpenAI API (embeddings)', 'AI Integration', 
          async () => {
            if (!process.env.OPENAI_API_KEY) throw new Error('No API key');
            await openai.embeddings.create({
              model: 'text-embedding-3-small',
              input: 'test',
              dimensions: 256
            });
          },
          { info: 500, warning: 1500, error: 5000 }
        ),
        
        // External services
        measureLatency('Stripe API', 'External Service', 
          async () => {
            if (!process.env.STRIPE_SECRET_KEY) throw new Error('No API key');
            const Stripe = await import('stripe');
            const stripe = new Stripe.default(process.env.STRIPE_SECRET_KEY);
            await stripe.balance.retrieve();
          },
          { info: 300, warning: 800, error: 2000 }
        ),
        
        // Geolocation (ip-api.com) - external service, more lenient thresholds
        measureLatency('/api/geolocation', 'External Service', 
          async () => {
            const response = await fetch('http://ip-api.com/json/?fields=status', { 
              signal: AbortSignal.timeout(3000) 
            });
            if (!response.ok) throw new Error('Failed');
          },
          { info: 500, warning: 1500, error: 3000 }
        ),
        
        // Exchange rates - external service, more lenient thresholds
        measureLatency('/api/exchange-rates', 'External Service', 
          async () => {
            const response = await fetch('https://api.frankfurter.app/latest?from=GBP', { 
              signal: AbortSignal.timeout(3000) 
            });
            if (!response.ok) throw new Error('Failed');
          },
          { info: 500, warning: 1500, error: 3000 }
        ),
      ]);
      
      // Sort by slowest first
      latencyMetrics.sort((a, b) => b.avgLatencyMs - a.avgLatencyMs);
      
      res.json(latencyMetrics);
    } catch (error) {
      console.error("Error fetching latency metrics:", error);
      res.status(500).json({ message: "Failed to fetch latency metrics" });
    }
  });


  // ==================== EMAIL LOGS MONITORING API ====================

  // Super Admin: Get email logs with filtering
  app.get("/api/admin/email-logs", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      if (user?.role !== 'super_admin') {
        return res.status(403).json({ message: "Forbidden: Super admin access required" });
      }
      
      const { recipientType, emailType, status, startDate, endDate, search, limit = '100', offset = '0' } = req.query;
      
      // Build where conditions
      const conditions: any[] = [];
      
      if (recipientType && recipientType !== 'all') {
        conditions.push(eq(emailLogs.recipientType, recipientType));
      }
      if (emailType && emailType !== 'all') {
        conditions.push(eq(emailLogs.emailType, emailType));
      }
      if (status && status !== 'all') {
        conditions.push(eq(emailLogs.status, status));
      }
      if (startDate) {
        conditions.push(gte(emailLogs.sentAt, new Date(startDate)));
      }
      if (search) {
        conditions.push(
          or(
            sql`${emailLogs.recipientEmail} ILIKE ${'%' + search + '%'}`,
            sql`${emailLogs.subject} ILIKE ${'%' + search + '%'}`
          )
        );
      }
      
      const query = conditions.length > 0
        ? db.select().from(emailLogs).where(and(...conditions))
        : db.select().from(emailLogs);
      
      const logs = await query
        .orderBy(desc(emailLogs.sentAt))
        .limit(parseInt(limit))
        .offset(parseInt(offset));
      
      // Get total count
      const countQuery = conditions.length > 0
        ? db.select({ count: sql<number>`count(*)` }).from(emailLogs).where(and(...conditions))
        : db.select({ count: sql<number>`count(*)` }).from(emailLogs);
      const [{ count }] = await countQuery;
      
      res.json({ logs, total: Number(count) });
    } catch (error) {
      console.error("Error fetching email logs:", error);
      res.status(500).json({ message: "Failed to fetch email logs" });
    }
  });

  // Super Admin: Get email log statistics
  app.get("/api/admin/email-logs/stats", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      if (user?.role !== 'super_admin') {
        return res.status(403).json({ message: "Forbidden: Super admin access required" });
      }
      
      const now = new Date();
      const last24Hours = new Date(now.getTime() - 24 * 60 * 60 * 1000);
      const last7Days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      
      const [total, sent24h, failed24h, byType, byRecipientType] = await Promise.all([
        db.select({ count: sql<number>`count(*)` }).from(emailLogs),
        db.select({ count: sql<number>`count(*)` }).from(emailLogs)
          .where(and(eq(emailLogs.status, 'sent'), gte(emailLogs.sentAt, last24Hours))),
        db.select({ count: sql<number>`count(*)` }).from(emailLogs)
          .where(and(eq(emailLogs.status, 'failed'), gte(emailLogs.sentAt, last24Hours))),
        db.select({ 
          type: emailLogs.emailType, 
          count: sql<number>`count(*)` 
        }).from(emailLogs)
          .groupBy(emailLogs.emailType)
          .orderBy(desc(sql`count(*)`)),
        db.select({ 
          recipientType: emailLogs.recipientType, 
          count: sql<number>`count(*)` 
        }).from(emailLogs)
          .groupBy(emailLogs.recipientType),
      ]);
      
      res.json({
        total: Number(total[0]?.count || 0),
        sent24h: Number(sent24h[0]?.count || 0),
        failed24h: Number(failed24h[0]?.count || 0),
        byType,
        byRecipientType,
      });
    } catch (error) {
      console.error("Error fetching email stats:", error);
      res.status(500).json({ message: "Failed to fetch email statistics" });
    }
  });

  // ==================== ACTIVE SESSIONS MONITORING API ====================

  // Super Admin: Get active sessions
  app.get("/api/admin/active-sessions", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);
      
      if (user?.role !== 'super_admin') {
        return res.status(403).json({ message: "Forbidden: Super admin access required" });
      }
      
      const now = new Date();
      
      // Get all non-expired sessions
      const activeSessions = await db.select().from(sessions)
        .where(gte(sessions.expire, now))
        .orderBy(desc(sessions.expire));
      
      // Parse session data and enhance with user info
      const enhancedSessions = await Promise.all(
        activeSessions.map(async (session) => {
          const sessData = session.sess as any;
          let userInfo = null;
          
          if (sessData?.passport?.user) {
            const sessionUser = await storage.getUser(sessData.passport.user);
            if (sessionUser) {
              userInfo = {
                id: sessionUser.id,
                email: sessionUser.email,
                firstName: sessionUser.firstName,
                lastName: sessionUser.lastName,
                role: sessionUser.role,
              };
            }
          }
          
          return {
            sid: session.sid,
            expire: session.expire,
            userInfo,
            createdAt: sessData?.cookie?.originalMaxAge ? 
              new Date(session.expire.getTime() - sessData.cookie.originalMaxAge) : null,
          };
        })
      );
      
      // Filter to only sessions with user info (authenticated sessions)
      const authenticatedSessions = enhancedSessions.filter(s => s.userInfo);
      
      // Get session statistics
      const totalActive = authenticatedSessions.length;
      const byRole: Record<string, number> = {};
      authenticatedSessions.forEach(s => {
        const role = s.userInfo?.role || 'unknown';
        byRole[role] = (byRole[role] || 0) + 1;
      });
      
      res.json({
        sessions: authenticatedSessions,
        stats: {
          totalActive,
          byRole,
        },
      });
    } catch (error) {
      console.error("Error fetching active sessions:", error);
      res.status(500).json({ message: "Failed to fetch active sessions" });
    }
  });

